47:     function beanstalkMint(
48:         address account,
49:         uint256 id,
50:         uint128 amount,
51:         uint128 bpf
52:     ) external onlyOwner {
53:         if (_balances[id][account].amount > 0) {
54:             uint256[] memory ids = new uint256[](1);
55:             ids[0] = id;
56:             _update(account, ids, bpf);
57:         }
58:         _balances[id][account].lastBpf = bpf;
59:         _safeMint(account, id, amount, bytes("0"));
60:     }
61: 
62:     function _beforeTokenTransfer(
63:         address, // operator,
64:         address from,
65:         address to,
66:         uint256[] memory ids,
67:         uint256[] memory, // amounts
68:         bytes memory // data
69:     ) internal virtual override {
70:         uint256 bpf = uint256(IBS(owner()).beansPerFertilizer());
71:         if (from != address(0)) _update(from, ids, bpf);
72:         _update(to, ids, bpf);
73:     }
74: 
75:     function _update(address account, uint256[] memory ids, uint256 bpf) internal {
76:         uint256 amount = __update(account, ids, bpf);
77:         if (amount > 0) IBS(owner()).payFertilizer(account, amount);
78:     }
79: 
80:     function __update(
81:         address account,
82:         uint256[] memory ids,
83:         uint256 bpf
84:     ) internal returns (uint256 beans) {
85:         for (uint256 i; i < ids.length; ++i) {
86:             uint256 stopBpf = bpf < ids[i] ? bpf : ids[i];
87:             uint256 deltaBpf = stopBpf - _balances[ids[i]][account].lastBpf;
88:             if (deltaBpf > 0) {
89:                 beans = beans.add(deltaBpf.mul(_balances[ids[i]][account].amount));
90:                 _balances[ids[i]][account].lastBpf = uint128(stopBpf);
91:             }
92:         }
93:         emit ClaimFertilizer(ids, beans);
94:     }
95: 
96:     function balanceOfFertilized(
97:         address account,
98:         uint256[] memory ids
99:     ) external view returns (uint256 beans) {
100:         uint256 bpf = uint256(IBS(owner()).beansPerFertilizer());
101:         for (uint256 i; i < ids.length; ++i) {
102:             uint256 stopBpf = bpf < ids[i] ? bpf : ids[i];
103:             uint256 deltaBpf = stopBpf - _balances[ids[i]][account].lastBpf;
104:             beans = beans.add(deltaBpf.mul(_balances[ids[i]][account].amount));
105:         }
106:     }
